import {browserFixture} from './generated-fixtures.ts';
import {readFileSync,mkdtempSync,writeFileSync,truncateSync,rmSync} from 'node:fs';
import {join} from 'node:path';
import {tmpdir} from 'node:os';
import {test,expect} from './fixtures.ts';
import {openPanel,closePanel,ready} from './browser-helpers.ts';
import {assertCanonicalState,assertSaveBytes} from './assertions.ts';

// Generated by P6_25_callback_boundaries_reopen_and_checkpoint_match_every_canonical_successor.
// Actual constructed stations/platforms and controlled P7 supply; production dispatch.
for(const mode of ['service','reverse','turning','midnight'])
for(const locale of ['en','ja'] as const)test(`P6-25 ${mode} ${locale} station slot download rejected uploads reconnect and process restart match uninterrupted run`,async({page,browser,baseURL,worldServer,sessions})=>{
 const input=browserFixture('stationContinuation');
 test.setTimeout(120000);
 const original=readFileSync(input!+'.'+mode),expected=readFileSync(input!+'.'+mode+'.expected');
 const text=JSON.parse(readFileSync(`src/locales/${locale}/app.json`,'utf8'));
 const saved=async()=>(await page.request.get('/api/saves/download')).body();
 const button=(name:string)=>page.getByRole('button',{name,exact:true});
 const errors:string[]=[];page.on('pageerror',e=>errors.push(String(e)));
 const owner=await sessions.observe(page,'owner');
 const exact=async(actual:Uint8Array,expected:Uint8Array,phase:string)=>assertSaveBytes(actual,expected,{phase,peer:'owner'});
 const secret=process.env.FREETRAIN_ONLINE_TEST_CONTAINER_IMAGE?'fleet-container-test':'';
 if(secret)expect((await page.request.post('/api/access',{data:{secret}})).ok()).toBe(true);
 await page.goto('/');await ready(page);
 await sessions.replaceSave(owner,original,'initial continuation save');
 await owner.reconnect(()=>page.reload(),owner.latest()!,'initial reload');await ready(page);
 if(locale==='ja'){
  await openPanel(page,'settings');await page.getByLabel('Language',{exact:true}).selectOption('ja');await closePanel(page);await ready(page,'ja');
 }
 const context=await browser.newContext({baseURL,locale:'ja-JP'}),peer=await context.newPage();
 const observer=await sessions.observe(peer,'observer');
 try{
  if(secret)expect((await peer.request.post('/api/access',{data:{secret:'observer-test'}})).ok()).toBe(true);
  await peer.goto('/');await ready(peer,'ja');await sessions.checkpoint(owner,'peer joined');
  await openPanel(page,'saves',locale);await page.getByLabel(text.saveSlot,{exact:true}).selectOption('slot2');
  await button(text.saveGame).click();await expect(page.getByTestId('save-feedback')).toHaveText(text.saved);
  const [download]=await Promise.all([page.waitForEvent('download'),button(text.downloadSave).click()]);
  await exact(readFileSync((await download.path())!),original,'slot download');
  const initial=await owner.ready(),epoch=initial.worldEpoch;
  const startMinute=Number(initial.tick);
  const badVersion=JSON.parse(original.toString());badVersion.saveVersion=8;
  const badPack=JSON.parse(original.toString());badPack.requiredPacks[0].catalogHash='0'.repeat(64);
  const badGraph=JSON.parse(original.toString());badGraph.mixed.stationGraph.platforms[0].hostId='999999';
  for(const [buffer,message] of [[Buffer.from('{broken'),text.invalidSave],[Buffer.from(JSON.stringify(badVersion)),text.incompatibleSave],
   [Buffer.from(JSON.stringify(badPack)),text.incompatibleSave],[Buffer.from(JSON.stringify(badGraph)),text.invalidSave]] as const){
   const upload=page.getByLabel(text.uploadSave,{exact:true});await expect(upload).toBeEnabled();
   await upload.setInputFiles({name:'rejected-station.json',mimeType:'application/json',buffer});
   await expect(page.getByTestId('save-feedback')).toContainText(message);
   await exact(await saved(),original,'rejected upload');expect((await owner.ready()).worldEpoch).toBe(epoch);
   await expect(page.locator('.decision-dialog')).toHaveCount(0);
  }
  const directory=mkdtempSync(join(tmpdir(),'station-oversize-')),large=join(directory,'large.json');
  try{
   writeFileSync(large,'x');truncateSync(large,256*1024*1024+1);
   const upload=page.getByLabel(text.uploadSave,{exact:true});await expect(upload).toBeEnabled();await upload.setInputFiles(large);
   await expect(page.getByTestId('save-feedback')).toHaveText(text.saveTooLarge);await exact(await saved(),original,'unchanged checkpoint');
  }finally{rmSync(directory,{recursive:true,force:true});}
  // Rejected uploads must leave the named file intact as well as the live world.
  await button(text.loadGame).click();await button(text.confirmLoad).click();
  // Loading identical bytes still replaces the world and closes its panels.
  // Wait for the new live draw before starting another panel interaction.
  for(const p of [page,peer])await expect(p.locator('.world-canvas')).toHaveAttribute('data-world-epoch',String(BigInt(epoch)+1n));
  await ready(page,locale);
  await exact(await saved(),original,'unchanged checkpoint');
  const loaded=await sessions.checkpoint(owner,'named slot replacement');
  await openPanel(page,'session',locale);await owner.reconnect(()=>button(text.reconnect).click(),loaded,'explicit reconnect');await ready(page,locale);
  await sessions.restartCheckpoint(worldServer,[{session:owner,secret},{session:observer,secret:secret?'observer-test':''}],'checkpoint restart');
  await ready(page,locale);await ready(peer,'ja');
  await exact(await saved(),original,'restarted checkpoint');
  // Continue from the minute before boarding through the second station unload.
  // Exact oracle includes listeners, origins, logs, bookings and queue ordering.
  for(let minute=startMinute+1;minute<=Number(JSON.parse(expected.toString()).clock.absoluteMinute);minute++){
   await sessions.minute(owner,()=>page.getByRole('button',{name:text.step,exact:false}).first().click(),`continuation minute ${minute}`);
  }
  await exact(await saved(),expected,'independent uninterrupted successor save');
  const target=await sessions.checkpoint(owner,'final continuation');
  await assertCanonicalState(target.mixed,JSON.parse(expected.toString()).mixed,{phase:'independent fixture successor',peer:'owner',...target});
  expect(errors).toEqual([]);
 }finally{await context.close();}
});
